<?php
declare(strict_types=1);
namespace App\Infrastructure\Persistence\Doctrine\QuestionLearning;
use App\Domain\QuestionLearning\Entity\QuestionComment;use App\Domain\QuestionLearning\Repository\QuestionCommentRepositoryInterface;use App\Infrastructure\Persistence\Doctrine\QuestionLearning\Entity\QuestionCommentRecord;use Doctrine\ORM\EntityManagerInterface;
final class DoctrineQuestionCommentRepository implements QuestionCommentRepositoryInterface { public function __construct(private readonly EntityManagerInterface $entityManager) {} public function listForQuestion(string $questionId, int $page, int $perPage): array { $records = $this->entityManager->createQueryBuilder()->select('comment')->from(QuestionCommentRecord::class, 'comment')->where('comment.questionId = :questionId')->setParameter('questionId', $questionId)->orderBy('comment.createdAt', 'ASC')->setFirstResult(($page - 1) * $perPage)->setMaxResults($perPage)->getQuery()->getResult(); return array_map($this->map(...), $records); } public function countForQuestion(string $questionId): int { return (int) $this->entityManager->createQueryBuilder()->select('COUNT(comment.id)')->from(QuestionCommentRecord::class, 'comment')->where('comment.questionId = :questionId')->setParameter('questionId', $questionId)->getQuery()->getSingleScalarResult(); } public function findForQuestion(string $commentId, string $questionId): ?QuestionComment { $record = $this->entityManager->find(QuestionCommentRecord::class, $commentId); return $record instanceof QuestionCommentRecord && $record->questionId === $questionId ? $this->map($record) : null; } public function save(QuestionComment $comment): void { $record = new QuestionCommentRecord(); $record->id = $comment->id; $record->questionId = $comment->questionId; $record->authorUserId = $comment->authorUserId; $record->parentId = $comment->parentId; $record->content = $comment->content; $record->createdAt = $comment->createdAt; $record->updatedAt = $comment->updatedAt; $this->entityManager->persist($record); $this->entityManager->flush(); } private function map(QuestionCommentRecord $record): QuestionComment { return new QuestionComment($record->id, $record->questionId, $record->authorUserId, $record->parentId, $record->content, $record->createdAt, $record->updatedAt); } }
